struct source * vcc_file_source ( struct vcc * tl , const char * fn ) { char * f , * fnp ; struct source * sp ; if ( ! tl -> unsafe_path && strchr ( fn , '/' ) != NULL ) { VSB_printf ( tl -> sb , "VCL filename '%s' is unsafe.\n" , fn ) ; tl -> err = 1 ; return ( NULL ) ; } f = NULL ; if ( VFIL_searchpath ( tl -> vcl_path , NULL , & f , fn , & fnp ) || f == NULL ) { VSB_printf ( tl -> sb , "Cannot read file '%s' (%s)\n" , fnp != NULL ?fnp : fn , strerror ( errno ) ) ; tl -> err = 1 ; return ( NULL ) ; } sp = vcc_new_source ( f , "file" , fnp ) ; free ( fnp ) ; return ( sp ) ; } 